import{_ as i,K as n,a as l,c as o,ac as e,b as r,q as d}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"易经：阴阳、卦画与六爻结构","description":"认识阴阳爻、三画卦和六画卦，练习由下往上读爻，区分卦序、爻位、变卦、错卦、综卦和互体。","frontmatter":{"title":"易经：阴阳、卦画与六爻结构","description":"认识阴阳爻、三画卦和六画卦，练习由下往上读爻，区分卦序、爻位、变卦、错卦、综卦和互体。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"认识阴阳爻、三画卦和六画卦，练习由下往上读爻，区分卦序、爻位、变卦、错卦、综卦和互体。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history"},"next":{"text":"易经：八卦名称、性质与取象","link":"/life/personal/yijing/trigrams"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history"},"next":{"text":"易经：八卦名称、性质与取象","link":"/life/personal/yijing/trigrams"}},"headers":[],"relativePath":"life/personal/yijing/symbols.md","filePath":"life/personal/yijing/symbols.md"}'),s={name:"life/personal/yijing/symbols.md"};function h(p,t,c,g,b,f){const a=n("ArticleImage");return l(),o("div",null,[t[0]||(t[0]=e(`<h1 id="易经-阴阳、卦画与六爻结构" tabindex="-1">易经：阴阳、卦画与六爻结构 <a class="header-anchor" href="#易经-阴阳、卦画与六爻结构" aria-label="Permalink to &quot;易经：阴阳、卦画与六爻结构&quot;">​</a></h1><p>易经的卦画只有两种基本线条，但线条的位置、组合和相互关系不同，组成的卦也不同。先把图读对，再谈卦义；一个上下颠倒的卦，会把后续的解释全部带偏。</p><h2 id="阴爻与阳爻" tabindex="-1">阴爻与阳爻 <a class="header-anchor" href="#阴爻与阳爻" aria-label="Permalink to &quot;阴爻与阳爻&quot;">​</a></h2><p>阳爻是一条连续的横画；阴爻是一条中间断开的横画。阴爻虽然画成两小段，仍然只算<strong>一爻</strong>。下列等宽字符是示意，正式图形见后面的本地图片。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阳爻：━━━━━━━━━</span></span>
<span class="line"><span>阴爻：━━━━ ━━━━</span></span></code></pre></div><p>在经传解释中，阳常与刚联系，阴常与柔联系，但“阳＝好、阴＝坏”不是通用规则。一卦中的行动是否适当还取决于时、位、关系和经文语境。坤卦是纯阴卦，当然不能因此被解释成“全坏”。<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3/%E8%AA%AA%E5%8D%A6" target="_blank" rel="noopener noreferrer">《说卦》第二章</a>把天道的阴阳、地道的柔刚、人道的仁义并列；这些概念有关联，却不是所有场景都能相互替换的标签。</p><h2 id="三画组成八卦" tabindex="-1">三画组成八卦 <a class="header-anchor" href="#三画组成八卦" aria-label="Permalink to &quot;三画组成八卦&quot;">​</a></h2><p>每个位置有阴、阳两种选择，三个位置共有 2×2×2＝8 种组合。这是现代组合计数对卦画的描述。八卦是乾、兑、离、震、巽、坎、艮、坤，排列顺序可以随用途改变，名称与图形的对应不变。</p>`,8)),r("p",null,[d(a,{src:"/life/yijing/trigrams.svg",alt:"八卦与从下向上的爻序编码"})]),t[1]||(t[1]=e('<p>图中用 1 表示阳、0 表示阴，<strong>左侧数字代表最下面一爻</strong>。例如震为 <code>100</code>：最下面是阳，中间和上面是阴；艮为 <code>001</code>：上面是阳。这个记录约定只帮助核对，不声称古人用现代二进制计算。</p><p>常见“乾三连、坤六断、震仰盂、艮覆碗、离中虚、坎中满、兑上缺、巽下断”是识图口诀。在<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">《周易本义》四库本所附卦歌</a>可见对应文字。口诀中的“坤六断”描述三条阴爻共六小段，不能误数成六爻。</p><h2 id="两个三画卦重成六画卦" tabindex="-1">两个三画卦重成六画卦 <a class="header-anchor" href="#两个三画卦重成六画卦" aria-label="Permalink to &quot;两个三画卦重成六画卦&quot;">​</a></h2><p>三画卦也常称经卦，六画卦也常称别卦、重卦。下方三个位置为下卦，又称内卦；上方三个位置为上卦，又称外卦。八种下卦各配八种上卦，就有 8×8＝64 卦。</p><table tabindex="0"><thead><tr><th>下卦</th><th>上卦</th><th>六画卦</th><th>应怎样读</th></tr></thead><tbody><tr><td>乾（天）</td><td>乾（天）</td><td>乾</td><td>上下皆乾</td></tr><tr><td>乾（天）</td><td>坤（地）</td><td>泰</td><td>地天泰：地在上、天在下</td></tr><tr><td>坤（地）</td><td>乾（天）</td><td>否</td><td>天地否：天在上、地在下</td></tr><tr><td>离（火）</td><td>坎（水）</td><td>既济</td><td>水火既济：水上火下</td></tr><tr><td>坎（水）</td><td>离（火）</td><td>未济</td><td>火水未济：火上水下</td></tr></tbody></table><p>“地天泰”这种复合称呼先说上卦，再说下卦；画爻和数爻却从下往上。这是初学时最容易交叉混淆的两套顺序。古籍正文只写“泰”“否”时，也已经有确定的卦画，不必把后起的复合卦名当作原卦辞的一部分。可对照<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B3%B0" target="_blank" rel="noopener noreferrer">泰</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%90%A6" target="_blank" rel="noopener noreferrer">否</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A2%E6%BF%9F" target="_blank" rel="noopener noreferrer">既济</a>的上下卦标注。</p><h2 id="六爻从下向上读" tabindex="-1">六爻从下向上读 <a class="header-anchor" href="#六爻从下向上读" aria-label="Permalink to &quot;六爻从下向上读&quot;">​</a></h2>',7)),r("p",null,[d(a,{src:"/life/yijing/line-positions.svg",alt:"既济卦的六爻位置与上下卦"})]),t[2]||(t[2]=e('<p>最下面为初爻，接着二、三、四、五，最上面为上爻。阳爻称九，阴爻称六，因此有“初九”“六二”“九三”等名称。“九五”表示第五个位置上的阳爻，不表示第九十五爻，也不表示第五爻永远是阳爻。</p><table tabindex="0"><thead><tr><th>位置</th><th>是阳爻时</th><th>是阴爻时</th><th>结构位置</th></tr></thead><tbody><tr><td>第一位</td><td>初九</td><td>初六</td><td>下卦之下</td></tr><tr><td>第二位</td><td>九二</td><td>六二</td><td>下卦之中</td></tr><tr><td>第三位</td><td>九三</td><td>六三</td><td>下卦之上</td></tr><tr><td>第四位</td><td>九四</td><td>六四</td><td>上卦之下</td></tr><tr><td>第五位</td><td>九五</td><td>六五</td><td>上卦之中</td></tr><tr><td>第六位</td><td>上九</td><td>上六</td><td>上卦之上</td></tr></tbody></table><p>“初”和“上”强调两端的处境，不是把人永久分成六个社会等级。注家经常借位谈君臣、进退和事物阶段，但六爻也不等于每个人必定经历的六个年龄段。</p><h2 id="_64-卦、384-爻-为什么还有用九与用六" tabindex="-1">64 卦、384 爻，为什么还有用九与用六 <a class="header-anchor" href="#_64-卦、384-爻-为什么还有用九与用六" aria-label="Permalink to &quot;64 卦、384 爻，为什么还有用九与用六&quot;">​</a></h2><p>64×6＝384，是六十四卦普通六爻的总数。乾的六爻之后另有“用九”，坤的六爻之后另有“用六”。它们是经文中的特殊条文，不能在乾坤卦图上再加第七画。不同注家会从纯阳、纯阴的运用或全爻变动等角度解释它们，详见<a href="./hexagrams-01-08">乾坤正文</a>和<a href="./divination">筮法</a>。</p><p>九、六也出现在传统筮数中；钱币法或蓍法还会产生七、八。不过，经书写“九二”并不等于任何一次得到这个位置都发生变动。<strong>爻题的九六是经文命名，某次起卦的动静是另外一层信息。</strong></p><h2 id="中、正与相应-先会看结构" tabindex="-1">中、正与相应：先会看结构 <a class="header-anchor" href="#中、正与相应-先会看结构" aria-label="Permalink to &quot;中、正与相应：先会看结构&quot;">​</a></h2><p>二、五处于内外卦的中间，常称“得中”。按常见爻位解释，阳居一、三、五，阴居二、四、六称“得正”或“当位”；二、五得中且当位可称“中正”。但古注对具体卦、初上两端及特殊时义有细致处理，不能靠这个表独立判吉凶。</p><p>相隔三个位置的一与四、二与五、三与上常被成对讨论，称“应”。阴阳相对通常称有应或正应，同类则常说无应；实际论断仍须看全卦。紧邻的爻可以讨论“比”，下爻承上爻称“承”，上爻凌于下爻称“乘”。这些是分析关系的工具，不是五条自动判卦公式。进阶例子见<a href="./hexagram-reading">读卦方法</a>。</p><h2 id="四种不同的变换-不能混为一谈" tabindex="-1">四种不同的变换，不能混为一谈 <a class="header-anchor" href="#四种不同的变换-不能混为一谈" aria-label="Permalink to &quot;四种不同的变换，不能混为一谈&quot;">​</a></h2><p>下表采用今日讲解中常见的术语约定；历代同名术语的范围并非始终一致。</p><table tabindex="0"><thead><tr><th>操作</th><th>具体做什么</th><th>例子</th><th>不能推出什么</th></tr></thead><tbody><tr><td>变爻与之卦</td><td>指定位置阴阳互换，其他位置保持</td><td>乾初九变阴，成姤</td><td>不是随意找一个意义相反的卦</td></tr><tr><td>错卦</td><td>六个位置全部阴阳互换</td><td>乾与坤；既济与未济</td><td>不等于任何起卦都必须六爻全动</td></tr><tr><td>综卦、覆卦</td><td>将六爻上下倒转</td><td>屯与蒙；泰与否</td><td>不是仅交换上下两个三画卦</td></tr><tr><td>互体、互卦</td><td>取原卦二三四为下卦，三四五为上卦</td><td>既济的互卦为未济</td><td>原卦初、上被舍去，不能当作原经文的同义替代</td></tr></tbody></table><p>例如乾的每条画都一样，上下倒转仍是乾；六爻全反则变成坤。所以“错”和“综”有时结果相同，有时完全不同。互体与卦变在易学史上应用很广，也受过批评，王弼<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E7%95%A5%E4%BE%8B/%E6%98%8E%E8%B1%A1" target="_blank" rel="noopener noreferrer">《周易略例·明象》</a>就提醒不要为了牵合物象不断追加解释。</p><h2 id="卦序也有不同用途" tabindex="-1">卦序也有不同用途 <a class="header-anchor" href="#卦序也有不同用途" aria-label="Permalink to &quot;卦序也有不同用途&quot;">​</a></h2><p>本专题正文采用传世《周易》的乾坤开始、既济未济结束的次序，通常称通行卦序或文王卦序。<a href="./diagrams">图书之学</a>还会遇到先天六十四卦排列；<a href="./traditions">后世传统</a>中会遇到八宫卦序。三者都包含六十四卦，但排列服务的问题不同，不能拿先天位置编号替代经书的卦序号。</p><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><ol><li>下卦为乾、上卦为坤，是泰还是否？</li><li>一条阴爻中间断开，算一爻还是两爻？</li><li>既济从下向上是阳阴阳阴阳阴，第五爻叫什么？</li><li>乾上下翻转与六爻全变，结果相同吗？</li></ol><p>答案：1. 泰。2. 一爻。3. 九五。4. 不同，翻转仍为乾，全变为坤。若这四题能说明理由，就可以进入<a href="./trigrams">八卦取象</a>与<a href="./hexagram-index">六十四卦索引</a>。</p><p><a href="./overview">返回易经专题导读</a></p>',19))])}const k=i(s,[["render",h]]);export{u as __pageData,k as default};
